/* Представление учебных материалов. Данные хранятся отдельно в learning.js. */
function lessonFormula(t,i){
 const [tex,note]=t.formulas[i],g=t.learning?.formulaGuides?.[i];
 if(!g)return `<div class="formula-card"><div class="formula-display">${math(tex,true)}</div><p class="formula-note">${rich(note)}</p></div>`;
 return `<section class="formula-card" id="formula-${t.id}-${i}"><h3 class="formula-name"><strong>${esc(g.title)}</strong></h3><div class="formula-display">${math(tex,true)}</div><p class="formula-meaning">${rich(g.meaning)}</p><p class="formula-condition"><strong>Когда использовать.</strong> ${rich(g.when)}</p><details class="formula-explanation"><summary>Обозначения, объяснение и пример</summary><dl class="symbol-grid">${g.symbols.map(([s,d])=>`<div><dt>${rich(s)}</dt><dd>${rich(d)}</dd></div>`).join('')}</dl><div class="reason"><h4>Почему формула устроена так</h4><p>${rich(g.why)}</p></div><div class="worked-example"><h4>Пример применения</h4><p>${rich(g.example)}</p></div><p class="formula-note">${rich(note)}</p></details></section>`;
}
function lessonBody(t,tab){
 const data=t.learning;
 if(tab==='theory')return `${data?.intuition?`<section class="intuition"><h2>Идея темы простыми словами</h2><p>${rich(data.intuition)}</p></section>`:''}${classroomScene(t)}<section class="article-section"><h2>Определения, которые объясняют эту ситуацию</h2><dl class="definitions">${t.definitions.map(([n,d])=>`<div class="definition"><dt>${esc(n)}</dt><dd>${rich(d)}</dd></div>`).join('')}</dl></section>${examFormulas(t)}${classroomExample(t)}${mistakes(t)}${oralSummary(t)}<div class="lesson-next"><p>Разобрались со смыслом? Теперь восстановите формулы из исходных законов.</p><button class="btn" data-tab="derive">Как получить эти формулы ${icon('arrow',16)}</button></div>`;
 if(tab==='derive')return `<section class="section-intro"><h2>Как получить формулу, а не заучить её</h2><p>Вывод — это цепочка от известных определений или законов к нужной формуле. На коллоквиуме важно объяснить, откуда вы начали, почему сделали каждый переход и где использовали приближение.</p><ol class="route-steps"><li>Прочитайте, что мы получаем и из чего начинаем.</li><li>Проследите решение по шагам. Назовите причину каждого перехода.</li><li>Закройте решение и повторите на бумаге без подсказки.</li></ol></section>${t.derivations.map(([name,steps],i)=>{const g=data?.derivationIntros?.[i];return `<section class="derivation-lesson"><header><span class="eyebrow">Разбор ${i+1} из ${t.derivations.length}</span><h2>${esc(name)}</h2></header>${g?`<dl class="derive-context"><div><dt>Что получим</dt><dd>${rich(g.goal)}</dd></div><div><dt>С чего начнём</dt><dd>${rich(g.start)}</dd></div><div><dt>Главная идея</dt><dd>${rich(g.logic)}</dd></div></dl>`:''}<details class="derivation" ${i===0?'open':''}><summary>Пошаговый разбор</summary><ol class="steps">${steps.map(s=>`<li>${rich(s)}</li>`).join('')}</ol></details>${g?`<div class="derive-check"><strong>Проверьте понимание.</strong> ${rich(g.check)}</div>`:''}</section>`;}).join('')}${mistakes(t)}<div class="lesson-next"><p>Теперь попробуйте восстановить вывод и применить формулы самостоятельно.</p><button class="btn" data-tab="check">Перейти к вопросам и задачам ${icon('arrow',16)}</button></div>`;
 return lessonPractice(t);
}
function practiceItems(t){return [...t.questions.map(([question,answer],i)=>({id:`q${i}`,kind:'Понимание',question,answer,solution:[],hint:'Начните с определения и укажите условия, при которых ваш ответ верен.'})),...(t.learning?.practice||[]).map((p,i)=>({...p,id:`p${i}`}))];}
function lessonPractice(t){const items=practiceItems(t),groups=[['Понимание','Проверить понятия'],['Задача','Применить формулы'],['Вывод','Восстановить вывод'],['Найди ошибку','Найти и объяснить ошибку']];const done=items.filter(p=>state.practice?.[`${topicKey(t)}:${p.id}`]==='done').length;
 return `<section class="section-intro"><h2>Проверить, что вы поняли тему</h2><p>Дайте свой ответ или решение, затем откройте разбор и сравните ход мысли. Если ошиблись, найдите конкретный шаг и вернитесь к соответствующей формуле.</p><p class="small muted">Все задания отмечены «Получилось» → тема получает статус «Могу объяснить». Отметка «Нужно разобрать ещё» → «Повторить». Черновик остаётся до закрытия страницы.</p><div class="practice-summary"><span>${items.length} заданий: понятия, применение, вывод и ошибки</span><strong id="practice-count">Получилось: ${done} / ${items.length}</strong></div></section><nav class="practice-jumps" aria-label="Виды заданий">${groups.filter(([kind])=>items.some(p=>p.kind===kind)).map(([kind,name],i)=>`<a href="#practice-section-${i}" data-practice-jump="${i}">${esc(name)}</a>`).join('')}</nav>${groups.map(([kind,name],group)=>{const list=items.filter(p=>p.kind===kind);if(!list.length)return '';return `<section class="practice-group" id="practice-section-${group}"><h2>${esc(name)}</h2>${list.map(p=>{const key=`${topicKey(t)}:${p.id}`,index=items.indexOf(p)+1,verdict=state.practice?.[key];return `<article class="practice-card"><div class="practice-meta"><span>Задание ${index}</span><span>${esc(kind)}</span><span class="practice-verdict" data-verdict="${esc(key)}">${verdict==='done'?'✓ Получилось':verdict==='again'?'Нужно повторить':''}</span></div><h3>${rich(p.question)}</h3><label class="answer-label" for="draft-${t.id}-${p.id}">Мой ответ или план решения</label><textarea id="draft-${t.id}-${p.id}" data-draft="${esc(key)}" rows="2" placeholder="Запишите ход мысли или ответьте вслух…">${esc(lessonDrafts[key]||'')}</textarea>${p.hint?`<details class="practice-hint"><summary>Небольшая подсказка</summary><p>${rich(p.hint)}</p></details>`:''}<details class="practice-solution"><summary>Сравнить с ответом и разбором</summary><div class="answer-result"><h4>Ответ</h4><p>${rich(p.answer)}</p></div>${p.solution?.length?`<h4>Как рассуждать</h4><ol>${p.solution.map(s=>`<li>${rich(s)}</li>`).join('')}</ol>`:''}<div class="practice-grade"><span>Сравните со своим решением:</span><button class="btn secondary" data-practice-grade="again" data-practice-key="${esc(key)}">Нужно разобрать ещё</button><button class="btn" data-practice-grade="done" data-practice-key="${esc(key)}">Получилось</button></div></details></article>`;}).join('')}</section>`;}).join('')}<div class="readiness"><h2>Когда тему можно считать освоенной</h2><p>Вы можете своими словами дать определения, объяснить обозначения и условия формул, восстановить основные выводы и решить задания с изменёнными числами. Одна прочитанная страница сама по себе этого не гарантирует.</p><a class="btn" href="#oral/${t.id}">Проверить полный устный ответ ${icon('arrow',16)}</a></div>`;
}
const lessonDrafts={};
document.addEventListener('input',e=>{if(e.target.matches('[data-draft]'))lessonDrafts[e.target.dataset.draft]=e.target.value;});
document.addEventListener('click',e=>{
 const jump=e.target.closest('[data-practice-jump]');if(jump){e.preventDefault();document.getElementById('practice-section-'+jump.dataset.practiceJump)?.scrollIntoView({behavior:'smooth',block:'start'});return;}
 const grade=e.target.closest('[data-practice-grade]');if(!grade)return;
 const key=grade.dataset.practiceKey;state.practice??={};state.practice[key]=grade.dataset.practiceGrade;save();
 for(const el of document.querySelectorAll('[data-verdict]'))if(el.dataset.verdict===key)el.textContent=grade.dataset.practiceGrade==='done'?'✓ Получилось':'Нужно повторить';
 const t=course().topics.find(t=>t.id===route().id);if(t){const items=practiceItems(t),done=items.filter(p=>state.practice?.[`${topicKey(t)}:${p.id}`]==='done').length;$('#practice-count').textContent=`Получилось: ${done} / ${items.length}`;let next=status(t);if(done===items.length)next=3;else if(grade.dataset.practiceGrade==='again')next=2;else if(next===0)next=1;state.progress[topicKey(t)]=next;save();if($('#topic-status'))$('#topic-status').value=String(next);$('.side-topics').innerHTML=sideTopics();if(done===items.length)toast('Все задания выполнены: тема отмечена «Могу объяснить».');}
});

